-- 011_auto_sku (applied 2026-11-11): item numbers are generated by the database,
-- unique across products and product_units. See migration in Supabase for full text.
create sequence if not exists public.item_sku_seq start 100001;
-- next_item_sku(): nextval until the number is free in both tables.
-- set_item_sku() trigger: fills empty sku, keeps the old one on update, rejects duplicates.
-- unique indexes products_sku_key, product_units_sku_key.
